changeSet.sql:
create or alter procedure [api].[DeleteExecutionRecords] 
 @numberOfDaysOlderThan int = 5
as
begin
	BEGIN TRANSACTION;
	SAVE TRANSACTION ApiDeleteSavePoint;

	BEGIN TRY
		-- delete records from child tables
		drop table if exists #ex;

		select	ExecutionID,
				Id
		into	#ex
		from	api.Execution e 
		where	[route] is not null 
				and [route] != 'BULK' 
				and DATEDIFF(day, e.CompletedOn, getutcdate()) > @numberOfDaysOlderThan

		create unique index uq_temp_ex on #ex (ExecutionID);
		create nonclustered index ix_temp_ex_Id on #ex (Id);

		if exists(select 1 from #ex)
		begin
			delete t from api.ExecutionAsset t inner join #ex ex on t.ExecutionId = ex.ExecutionId;
			delete t from api.ExecutionAssetCrossReference t inner join #ex ex on t.ExecutionId = ex.ExecutionId;
			delete t from api.ExecutionAssetDataProfile t inner join #ex ex on t.ExecutionId = ex.ExecutionId;
			delete t from api.ExecutionAssetDataProfileSample t inner join #ex ex on t.ExecutionId = ex.ExecutionId;
			delete t from api.ExecutionAssetError t inner join #ex ex on t.ExecutionId = ex.ExecutionId;
			delete t from api.ExecutionAssetResult t inner join #ex ex on t.ExecutionId = ex.ExecutionId;
			delete t from api.ExecutionCatalogItem t inner join #ex ex on t.ExecutionId = ex.Id;
			delete t from api.ExecutionCatalogItemProperty t inner join #ex ex on t.ExecutionId = ex.Id;
			delete t from api.ExecutionDeleteAssetDataProfile t inner join #ex ex on t.ExecutionId = ex.ExecutionId;
			delete t from api.ExecutionDeleteAssetResult t inner join #ex ex on t.ExecutionId = ex.ExecutionId;
			delete t from api.ExecutionDeletedAsset t inner join #ex ex on t.ExecutionId = ex.ExecutionId;
			delete t from api.ExecutionDeletedAssetType t inner join #ex ex on t.ExecutionId = ex.ExecutionId;
			delete t from api.ExecutionDeletedGroup t inner join #ex ex on t.ExecutionId = ex.ExecutionId; 
			delete t from api.ExecutionDeletedPredicate t inner join #ex ex on t.ExecutionId = ex.ExecutionId;
			delete t from api.ExecutionDeletedRelationship t inner join #ex ex on t.ExecutionId = ex.ExecutionId;
			delete t from api.ExecutionDeletedRelationshipType t inner join #ex ex on t.ExecutionId = ex.ExecutionId;
			delete t from api.ExecutionDiagramAsset t inner join #ex ex on t.ExecutionId = ex.ExecutionId;
			delete t from api.ExecutionDiagramAssetField t inner join #ex ex on t.ExecutionId = ex.ExecutionId;
			delete t from api.ExecutionField t inner join #ex ex on t.ExecutionId = ex.ExecutionId;
			delete t from api.ExecutionGroup t inner join #ex ex on t.ExecutionId = ex.ExecutionId;
			delete t from api.ExecutionItemDependentChange t inner join #ex ex on t.ExecutionId = ex.ExecutionId;
			delete t from api.ExecutionMeasure t inner join #ex ex on t.ExecutionId = ex.ExecutionId;
			delete t from api.ExecutionPredicate t inner join #ex ex on t.ExecutionId = ex.ExecutionId;
			delete t from api.ExecutionRelationship t inner join #ex ex on t.ExecutionId = ex.ExecutionId;
			delete t from api.ExecutionRelationshipError t inner join #ex ex on t.ExecutionId = ex.ExecutionId;
			delete t from api.ExecutionRelationshipType t inner join #ex ex on t.ExecutionId = ex.ExecutionId;
			delete t from api.ExecutionResponsibilityType t inner join #ex ex on t.ExecutionId = ex.ExecutionId;
			delete t from api.ExecutionResponsibilityTypeRelationOverrideItem t inner join #ex ex on t.ExecutionId = ex.ExecutionId;
			delete t from api.ExecutionScore t inner join #ex ex on t.ExecutionId = ex.ExecutionId;
			delete t from api.ExecutionUser t inner join #ex ex on t.ExecutionId = ex.ExecutionId;

			-- Finally, delete execution header record.
			delete t from api.Execution t inner join #ex ex on t.ExecutionId = ex.ExecutionId;
		end

		-- delete any score records that are not completed, and have a status of -1
		delete	api.Execution 
		where	[method] = 'score' 
				and state = -1  
				and completedon is null 
				and DATEDIFF(day, startedon, getutcdate()) > @numberOfDaysOlderThan;

		delete	i
		from	[metrics].[ExecutionItem] i
				inner join [metrics].[Execution] e on e.ID = i.ExecutionID 
					and e.CompletedOn is not null 
					and DATEDIFF(day, e.CompletedOn, getutcdate()) > @numberOfDaysOlderThan;

		delete	[metrics].[Execution]
		where	CompletedOn is not null 
				and DATEDIFF(day, CompletedOn, getutcdate()) > @numberOfDaysOlderThan;

		COMMIT TRANSACTION 
	END TRY
	BEGIN CATCH
		IF @@TRANCOUNT > 0
		BEGIN
			ROLLBACK TRANSACTION ApiDeleteSavePoint; -- rollback to MySavePoint
		END
	END CATCH
end
